from __future__ import annotations

from pathlib import Path

D1_PATH = Path(__file__).with_name("recovery_d1_runner.py")
source = D1_PATH.read_text(encoding="utf-8")

needle = '''# Post-Quick only: freeze the canonical deterministic diff review.\nrun(str(py), "-B", "skillctl.py", "repair-diff-review", "--decision", "PASS")\n'''
replacement = '''# Post-Quick only: reconcile the one known machine-local runtime byproduct\n# using the controller's own workspace-manifest semantics. The historical\n# recovery root is reconstructed with git archive and is intentionally not a\n# Git working tree, so git check-ignore/ls-files are not valid evidence here.\n# This is not a scope exclusion: the unchanged canonical repair-diff-review\n# below remains the final fail-closed scope authority.\npre_diff = load(runner_temp / "recovery-h3-readonly-diff-proof.json")\nassert pre_diff["status"] == "PASS", pre_diff\nassert pre_diff["changed_paths"] == EXPECTED_CHANGED_PATHS, pre_diff\nassert pre_diff["out_of_scope_paths"] == [], pre_diff\n\nruntime_rel = "services/agent-service/runtime/vector-store/vector_store.db"\nruntime_db = ROOT / runtime_rel\nignore_file = ROOT / "services/agent-service/.gitignore"\nignore_text = ignore_file.read_text(encoding="utf-8")\nassert "# Runtime state is machine-local and never belongs to source or a release archive." in ignore_text\nassert "runtime/**" in ignore_text\nassert not (ROOT / ".git").exists(), "historical archive root unexpectedly became a Git working tree"\n\n# Reuse the same deterministic manifest model used by repair governance.\nimport sys\nsys.path.insert(0, str(ROOT / "skill-system/controller"))\nfrom repair_governance import capture_workspace_manifest, load_chain  # type: ignore\n\ncontract = load(ROOT / "governance/active-change.json")\nchain = load_chain(ROOT, contract, include_diff=False, include_closure=False)\nbaseline_files = chain.baseline["workspace_files"]\nassert runtime_rel not in baseline_files, "runtime DB unexpectedly belongs to frozen baseline source"\n\n# Fail closed on any filesystem shape other than absent or one regular file at\n# the exact known runtime path. Symlinks/directories are never cleaned.\nassert not runtime_db.is_symlink(), f"runtime artifact unexpectedly symlinked: {runtime_rel}"\nif runtime_db.exists():\n    assert runtime_db.is_file(), f"runtime artifact is not a regular file: {runtime_rel}"\nruntime_present = runtime_db.is_file()\n\ncurrent_files = capture_workspace_manifest(ROOT)\nchanged_after_quick = sorted(\n    path for path in set(baseline_files) | set(current_files)\n    if baseline_files.get(path) != current_files.get(path)\n)\nexpected_after_quick = sorted(EXPECTED_CHANGED_PATHS + ([runtime_rel] if runtime_present else []))\nassert changed_after_quick == expected_after_quick, {\n    "changed_after_quick": changed_after_quick,\n    "expected_after_quick": expected_after_quick,\n}\n\ncleanup_record = {\n    "schema_version": 1,\n    "phase": "Closure-D1d-runtime-hygiene",\n    "status": "PASS",\n    "path": runtime_rel,\n    "archive_root_has_git_metadata": False,\n    "baseline_contains_runtime_path": False,\n    "present_after_quick": runtime_present,\n    "pre_quick_candidate_paths": pre_diff["changed_paths"],\n    "post_quick_manifest_changed_paths": changed_after_quick,\n    "pre_quick_out_of_scope_paths": pre_diff["out_of_scope_paths"],\n    "policy": "services/agent-service/.gitignore: runtime/** is machine-local and not source/release state",\n    "proof_model": "repair_governance.capture_workspace_manifest against frozen baseline workspace_files",\n}\n\nif runtime_present:\n    runtime_db.unlink()\n    assert not runtime_db.exists(), f"runtime artifact cleanup failed: {runtime_rel}"\n    cleanup_record["action"] = "removed_exact_machine_local_byproduct"\nelse:\n    cleanup_record["action"] = "known_machine_local_byproduct_absent"\n\npost_cleanup_files = capture_workspace_manifest(ROOT)\nchanged_post_cleanup = sorted(\n    path for path in set(baseline_files) | set(post_cleanup_files)\n    if baseline_files.get(path) != post_cleanup_files.get(path)\n)\nassert changed_post_cleanup == EXPECTED_CHANGED_PATHS, {\n    "changed_post_cleanup": changed_post_cleanup,\n    "expected": EXPECTED_CHANGED_PATHS,\n}\ncleanup_record["post_cleanup_manifest_changed_paths"] = changed_post_cleanup\n\n(runner_temp / "recovery-d1d-runtime-hygiene.json").write_text(\n    json.dumps(cleanup_record, ensure_ascii=False, indent=2) + "\\n",\n    encoding="utf-8",\n)\n\n# Final authority remains the unchanged canonical deterministic diff review.\nrun(str(py), "-B", "skillctl.py", "repair-diff-review", "--decision", "PASS")\n'''

if needle not in source:
    raise SystemExit("D1 post-Quick diff-review insertion point changed; fail closed")
patched = source.replace(needle, replacement, 1)
exec(compile(patched, str(D1_PATH) + "[D1d]", "exec"), {"__name__": "__main__", "__file__": str(D1_PATH)})
